import numpy as np
import os
import matplotlib.pyplot as plt


def eval():
    pred_dir = "pred_results"

    # Check predicted files exist
    pred_txt = os.path.join(pred_dir, "pred_plot_acc.txt")
    pred_png = os.path.join(pred_dir, "pred_plot_acc_L100.png")

    for f, label in [(pred_txt, "pred txt"), (pred_png, "pred png")]:
        if not os.path.exists(f):
            return (False, f"Missing file: {f}")

    # Check PNG is valid (> 1KB)
    if os.path.getsize(pred_png) < 1024:
        return (False, "Predicted plot image is too small (< 1KB), likely invalid")

    # Load predicted text data
    try:
        pred_data = np.loadtxt(pred_txt)
    except Exception as <local-path>        return (False, f"Failed to load predicted text file: {e}")

    # Validate shape: should have 2 rows
    if pred_data.ndim != 2 or pred_data.shape[0] != 2:
        return (False, f"Predicted data should have 2 rows, got shape: {pred_data.shape}")

    # Should have 16 columns (SNR from -10 to 20 in steps of 2)
    if pred_data.shape[1] != 16:
        return (False, f"Predicted data should have 16 columns (SNR points), got {pred_data.shape[1]}")

    pred_snr = pred_data[0]
    pred_acc = pred_data[1]

    # Check SNR values match expected range (-10 to 20 in steps of 2)
    expected_snr = np.arange(-10, 21, 2, dtype=float)
    if not np.allclose(pred_snr, expected_snr, atol=0.5):
        return (False, f"SNR values don't match expected range -10 to 20 in steps of 2. Got: {pred_snr}")

    # Check accuracy values are in valid range [0, 1]
    if np.any(pred_acc < 0) or np.any(pred_acc > 1.01):
        return (False, f"Accuracy values out of range [0, 1]: min={pred_acc.min():.4f}, max={pred_acc.max():.4f}")

    # Check that accuracy generally increases with SNR (monotonic trend check - relaxed)
    # At high SNR (>= 10 dB), accuracy should be reasonably high
    high_snr_indices = pred_snr >= 10
    high_snr_acc = pred_acc[high_snr_indices]
    if len(high_snr_acc) > 0 and np.mean(high_snr_acc) < 0.3:
        return (False, f"Accuracy at high SNR (>=10 dB) seems too low: mean={np.mean(high_snr_acc):.4f}")

    # Check that accuracy at low SNR is lower than at high SNR (general trend)
    low_snr_indices = pred_snr <= -6
    low_snr_acc = pred_acc[low_snr_indices]
    if len(low_snr_acc) > 0 and len(high_snr_acc) > 0:
        if np.mean(low_snr_acc) > np.mean(high_snr_acc) + 0.1:
            return (False, f"Accuracy trend is unexpected: low SNR acc ({np.mean(low_snr_acc):.4f}) > high SNR acc ({np.mean(high_snr_acc):.4f})")

    # Try to compare with gold standard if it exists (optional, non-blocking check)
    gold_dir = "./gold_results/"
    gold_txt = os.path.join(gold_dir, "pred_plot_acc.txt")

    if os.path.exists(gold_txt):
        try:
            gold_data = np.loadtxt(gold_txt)
            if gold_data.shape == (2, 16):
                gold_acc = gold_data[1]
                gold_snr = gold_data[0]

                # Check if SNR values match between gold and pred
                if np.allclose(pred_snr, gold_snr, atol=0.5):
                    # Use a more lenient tolerance for accuracy comparison
                    # since different valid file paths may yield slightly different results
                    max_diff = np.max(np.abs(pred_acc - gold_acc))
                    if max_diff > 0.05:  # 5% tolerance - more lenient
                        return (False, f"Accuracy values differ significantly from gold standard. "
                                      f"Max difference: {max_diff:.4f}. "
                                      f"Pred acc: {pred_acc}, Gold acc: {gold_acc}")
        except Exception as <local-path>            # If gold comparison fails, don't penalize - rely on structural checks
            pass

    # Verify the PNG file can be opened as a valid image
    try:
        img = plt.imread(pred_png)
        if img is None or img.size == 0:
            return (False, "PNG file appears to be empty or invalid")
    except Exception as <local-path>        return (False, f"Could not read PNG file as image: {e}")

    return (True, f"All checks passed: SNR values correct (-10 to 20 dB, 16 points), "
                  f"accuracy values in valid range [0,1], "
                  f"accuracy trend is physically reasonable, "
                  f"plot file exists and is valid. "
                  f"Accuracy values: {pred_acc}")


