import numpy as np
import os
from PIL import Image


def eval():
    pred_npy_path = "pred_results/pred_plot_confusion_matrix.npy"
    pred_png_path = "pred_results/pred_plot_confusion_matrix.png"
    gold_npy_path = "./gold_results/pred_plot_confusion_matrix.npy"

    # Step 1: Check file existence
    if not os.path.exists(pred_npy_path):
        return (False, f"Missing predicted npy file: {pred_npy_path}")
    if not os.path.exists(pred_png_path):
        return (False, f"Missing predicted png file: {pred_png_path}")

    # Step 2: Load and validate shape/dtype of predicted npy
    try:
        pred = np.load(pred_npy_path)
    except Exception as <local-path>        return (False, f"Failed to load predicted npy: {e}")

    if pred.shape != (4, 4):
        return (False, f"Expected shape (4, 4), got {pred.shape}")

    if not np.issubdtype(pred.dtype, np.floating):
        return (False, f"Expected float dtype, got {pred.dtype}")

    # Step 3: Verify normalization - values should be in [0, 1]
    if pred.min() < -0.001 or pred.max() > 1.001:
        return (False, f"Values out of range [0,1]: min={pred.min()}, max={pred.max()}")

    # Step 4: Check that the matrix is normalized in some reasonable way
    # Either row sums ~1.0 (row normalization) or divided by average samples per class
    row_sums = pred.sum(axis=1)
    total_sum = pred.sum()

    # Accept either row-normalized (each row sums to ~1) or normalized by average count
    # For row normalization: each row sum should be ~1.0
    row_normalized = all(abs(rs - 1.0) < 0.05 for rs in row_sums)

    # For normalization by average: total sum should be ~4.0 (if average = total/4)
    # or values should be reasonable fractions
    avg_normalized = (0.5 < total_sum < 8.0) and pred.max() <= 1.001

    if not row_normalized and not avg_normalized:
        return (False, f"Matrix does not appear to be properly normalized. Row sums: {row_sums}, total: {total_sum}")

    # Step 5: Validate PNG image
    try:
        img = Image.open(pred_png_path)
        w, h = img.size
        if w < 300 or h < 300:
            return (False, f"Image too small: {w}x{h}, expected at least 300x300")
    except Exception as <local-path>        return (False, f"Failed to read PNG image: {e}")

    # Step 6: Compare against gold standard if available
    if os.path.exists(gold_npy_path):
        try:
            gold = np.load(gold_npy_path)
        except Exception as <local-path>            # If gold can't be loaded, skip this check
            gold = None

        if gold is not None and gold.shape == pred.shape:
            # Check if they match with reasonable tolerance
            if np.allclose(pred, gold, atol=0.02):
                return (True, "All checks passed: correct shape, normalization, value range, and matches gold standard.")

            # If they don't match exactly, check if they represent the same underlying data
            # by comparing relative patterns (in case of different normalization methods)
            # Try to see if pred is proportional to gold (same pattern, different scale)
            gold_flat = gold.flatten()
            pred_flat = pred.flatten()

            # Check correlation - both should represent the same confusion matrix
            if gold_flat.std() > 0 and pred_flat.std() > 0:
                correlation = np.corrcoef(gold_flat, pred_flat)[0, 1]
                if correlation > 0.99:
                    # Same pattern, just different normalization - acceptable
                    return (True, f"Checks passed: correct shape, values in range, high correlation with gold ({correlation:.4f}).")

            max_diff = np.max(np.abs(pred - gold))
            # Be lenient - if values are close enough, pass
            if max_diff < 0.05:
                return (True, f"Checks passed with small differences (max diff: {max_diff:.4f}).")

            return (False, f"Normalized confusion matrix values differ from gold. Max diff: {max_diff:.4f}. Row sums: {row_sums}")

    # If no gold standard, pass based on structural checks
    return (True, "Checks passed: correct shape, normalization, and value range (no gold standard for comparison).")

