import re
import os


def parse_density_file(filepath):
    """Parse a density output file and extract volume, mass, and density values."""
    if not os.path.exists(filepath):
        return None, f"File not found: {filepath}"

    with open(filepath, 'r') as <local-path>        content = f.read()

    values = {}

    # Try to extract volume - flexible pattern matching
    patterns_volume = [
        r'[Vv]olume\s*[\(（][^)）]*[Aa]ngstrom[^)）]*[)）]\s*[:=]\s*([\d.eE+-]+)',
        r'[Vv]olume\s*[\(（][^)）]*[)）]\s*[:=]\s*([\d.eE+-]+)',
        r'[Vv]olume\s*[:=]\s*([\d.eE+-]+)',
    ]
    for pattern in patterns_volume:
        m = re.search(pattern, content)
        if <local-path>            values['volume'] = float(m.group(1))
            break

    # Try to extract mass - flexible pattern matching
    patterns_mass = [
        r'[Tt]otal\s+[Mm]ass\s*[\(（][^)）]*[Aa][Mm][Uu][^)）]*[)）]\s*[:=]\s*([\d.eE+-]+)',
        r'[Mm]ass\s*[\(（][^)）]*[Aa][Mm][Uu][^)）]*[)）]\s*[:=]\s*([\d.eE+-]+)',
        r'[Tt]otal\s+[Mm]ass\s*[:=]\s*([\d.eE+-]+)',
        r'[Mm]ass(?:es)?\s*[:=]\s*([\d.eE+-]+)',
    ]
    for pattern in patterns_mass:
        m = re.search(pattern, content)
        if <local-path>            values['mass'] = float(m.group(1))
            break

    # Try to extract density - flexible pattern matching
    patterns_density = [
        r'[Dd]ensity\s*[\(（][^)）]*[Gg]/[Cc][Mm][^)）]*[)）]\s*[:=]\s*([\d.eE+-]+)',
        r'[Dd]ensity\s*[:=]\s*([\d.eE+-]+)',
    ]
    for pattern in patterns_density:
        m = re.search(pattern, content)
        if <local-path>            values['density'] = float(m.group(1))
            break

    return values, None


def compute_expected_values(trajectory_path):
    """Compute expected density values directly from the trajectory file."""
    try:
        from ase.io import read
        import numpy as np

        atoms = read(trajectory_path, index=-1)
        volume_Angstrom3 = atoms.get_volume()
        total_mass_amu = sum(atoms.get_masses())

        # Standard unit conversion: 1 amu/Angstrom^3 = 1.66053906660 g/cm^3
        density_g_per_cm3 = (total_mass_amu * 1.66053906660) / volume_Angstrom3

        return {
            'volume': volume_Angstrom3,
            'mass': total_mass_amu,
            'density': density_g_per_cm3
        }, None
    except Exception as <local-path>        return None, f"Error computing expected values: {str(e)}"


def eval():
    pred_path = "pred_results/pred_density.txt"
    trajectory_path = "benchmark/datasets/I-ReaxFF/test/md.traj"

    # Check pred file exists
    if not os.path.exists(pred_path):
        return (False, f"Predicted output file not found: {pred_path}")

    # Try to get gold values from gold file first, fall back to computing from trajectory
    gold_path = "./gold_results/pred_density.txt"

    if os.path.exists(gold_path):
        gold_values, err = parse_density_file(gold_path)
        if err or not gold_values:
            # Fall back to computing from trajectory
            gold_values, err = compute_expected_values(trajectory_path)
            if err:
                return (False, f"Error computing expected values: {err}")
    else:
        # Compute expected values directly from trajectory
        gold_values, err = compute_expected_values(trajectory_path)
        if err:
            return (False, f"Error computing expected values: {err}")

    # Check all required values are present in gold
    for key in ['volume', 'mass', 'density']:
        if key not in gold_values:
            return (False, f"Gold/expected values missing required key: {key}")

    # Parse prediction file
    pred_values, err = parse_density_file(pred_path)
    if err:
        return (False, f"Error reading predicted file: {err}")

    # Check all required values are present in prediction
    missing_keys = []
    for key in ['volume', 'mass', 'density']:
        if key not in pred_values:
            missing_keys.append(key)

    if missing_keys:
        return (False, f"Predicted file missing required values: {missing_keys}. File content:\n{open(pred_path).read()}")

    # Compare volume (0.1% relative error tolerance)
    rel_err_volume = abs(pred_values['volume'] - gold_values['volume']) / gold_values['volume']
    if rel_err_volume > 0.001:
        return (False, f"Volume mismatch: predicted={pred_values['volume']:.6f}, expected={gold_values['volume']:.6f}, relative_error={rel_err_volume:.6e}")

    # Compare mass (0.01% relative error tolerance)
    rel_err_mass = abs(pred_values['mass'] - gold_values['mass']) / gold_values['mass']
    if rel_err_mass > 0.0001:
        return (False, f"Mass mismatch: predicted={pred_values['mass']:.6f}, expected={gold_values['mass']:.6f}, relative_error={rel_err_mass:.6e}")

    # Compare density (0.5% relative error tolerance - allows for slightly different unit conversion constants)
    rel_err_density = abs(pred_values['density'] - gold_values['density']) / gold_values['density']
    if rel_err_density > 0.005:
        return (False, f"Density mismatch: predicted={pred_values['density']:.6f}, expected={gold_values['density']:.6f}, relative_error={rel_err_density:.6e}")

    return (True, f"All checks passed. Volume rel_err={rel_err_volume:.2e}, Mass rel_err={rel_err_mass:.2e}, Density rel_err={rel_err_density:.2e}")


