import os


def eval():
    pred_file = "pred_results/pred_get_maccs.txt"
    gold_file = "./gold_results/pred_get_maccs.txt"

    # Check files exist
    if not os.path.exists(pred_file):
        return (False, "Predicted output file not found: " + pred_file)
    if not os.path.exists(gold_file):
        return (False, "Gold standard file not found: " + gold_file)

    # Check file is not empty
    if os.path.getsize(pred_file) == 0:
        return (False, "Predicted output file is empty (0 bytes). The solution may have failed to execute properly.")

    # Parse a results file into list of (smiles, fingerprint) tuples
    def parse_file(filepath):
        entries = []
        with open(filepath, "r") as <local-path>            for line_num, line in enumerate(f, 1):
                line = line.strip()
                if not line:
                    continue
                parts = line.split("\t")
                if len(parts) < 2:
                    return None, f"Line {line_num} in {filepath} is not tab-separated: '{line[:50]}'"
                smiles = parts[0]
                fingerprint = parts[1]
                entries.append((smiles, fingerprint))
        return entries, None

    gold_entries, err = parse_file(gold_file)
    if err:
        return (False, f"Error parsing gold file: {err}")

    pred_entries, err = parse_file(pred_file)
    if err:
        return (False, f"Error parsing predicted file: {err}")

    if len(pred_entries) == 0:
        return (False, "Predicted output file is empty or has no valid tab-separated entries")

    if len(gold_entries) == 0:
        return (False, "Gold standard file is empty")

    # Validate format of predicted fingerprints
    invalid_fps = []
    for smiles, fp in pred_entries:
        fp_len = len(fp)
        # Accept 166 or 167 bits (MACCS keys - RDKit uses 167, task says 166)
        if fp_len not in (166, 167):
            invalid_fps.append(f"'{smiles[:20]}' has length {fp_len}")
        elif not all(c in '01' for c in fp):
            invalid_fps.append(f"'{smiles[:20]}' contains non-binary characters")

    if invalid_fps:
        return (False, f"Invalid fingerprint format for entries: {invalid_fps[:3]}")

    # Build gold lookup by SMILES for flexible matching
    gold_by_smiles = {smiles: fp for smiles, fp in gold_entries}
    pred_by_smiles = {smiles: fp for smiles, fp in pred_entries}

    # Match predicted entries against gold
    exact_matches = 0
    total_bit_accuracy = 0.0
    matched_count = 0
    mismatches = []

    for smiles, gold_fp in gold_entries:
        if smiles not in pred_by_smiles:
            continue
        matched_count += 1
        pred_fp = pred_by_smiles[smiles]

        # Handle length differences: if gold is 167 and pred is 166, 
        # compare by aligning (skip bit 0 of gold, or compare truncated)
        if len(pred_fp) == len(gold_fp):
            compare_pred = pred_fp
            compare_gold = gold_fp
        elif len(pred_fp) == 166 and len(gold_fp) == 167:
            # Gold has 167 bits (bit 0 unused), pred has 166 bits (bits 1-166)
            compare_pred = pred_fp
            compare_gold = gold_fp[1:]
        elif len(pred_fp) == 167 and len(gold_fp) == 166:
            # Pred has 167 bits, gold has 166 bits
            compare_pred = pred_fp[1:]
            compare_gold = gold_fp
        else:
            compare_pred = pred_fp
            compare_gold = gold_fp

        # Compute matching bits
        min_len = min(len(compare_pred), len(compare_gold))
        max_len = max(len(compare_pred), len(compare_gold))
        matching_bits = sum(1 for a, b in zip(compare_pred[:min_len], compare_gold[:min_len]) if a == b)
        bit_acc = matching_bits / max_len

        if compare_pred == compare_gold:
            exact_matches += 1
        else:
            if len(mismatches) < 5:
                mismatches.append((smiles, pred_fp, gold_fp, bit_acc))

        total_bit_accuracy += bit_acc

    if matched_count == 0:
        # Provide helpful debugging info
        gold_smiles_sample = list(gold_by_smiles.keys())[:3]
        pred_smiles_sample = list(pred_by_smiles.keys())[:3]
        return (False, 
                f"No SMILES in predicted output matched gold standard SMILES. "
                f"Gold sample: {gold_smiles_sample}. "
                f"Pred sample: {pred_smiles_sample}.")

    # Processing success rate: how many gold SMILES were found in predictions
    processing_rate = matched_count / len(gold_entries)
    exact_match_accuracy = exact_matches / matched_count
    avg_bit_accuracy = total_bit_accuracy / matched_count

    # Apply thresholds
    reasons = []

    if processing_rate < 0.90:
        reasons.append(
            f"Processing rate {processing_rate:.2%} < 90% "
            f"({matched_count}/{len(gold_entries)} gold SMILES found in predictions)"
        )

    if exact_match_accuracy < 0.90:
        reasons.append(
            f"Exact match accuracy {exact_match_accuracy:.2%} < 90% "
            f"({exact_matches}/{matched_count} matched)"
        )
        if mismatches:
            mismatch_info = []
            for sm, pred, gold, bacc in mismatches[:3]:
                mismatch_info.append(
                    f"SMILES: {sm[:30]}, pred_len={len(pred)}, gold_len={len(gold)}, bit_acc={bacc:.3f}"
                )
            reasons.append(f"Sample mismatches: {mismatch_info}")

    if avg_bit_accuracy < 0.98:
        reasons.append(f"Average bit-wise accuracy {avg_bit_accuracy:.4%} < 98%")

    if reasons:
        return (False, "; ".join(reasons))

    return (
        True,
        f"All checks passed: exact match accuracy {exact_match_accuracy:.2%}, "
        f"bit-wise accuracy {avg_bit_accuracy:.4%}, "
        f"processing rate {processing_rate:.2%} "
        f"({matched_count}/{len(gold_entries)} entries matched)"
    )
